For any $\varepsilon > 0$, there exist $C, \delta > 0$ such that the following holds. 
Let $x > 2$, $(\log x)^C \le y \le x^{1/C}$, and denote $u := (\log x)/(\log y)$, $H(u) := \exp \left(u \log^{-2} (u+1)\right)$. Then with an exponent of
\begin{equation} 
    \alpha := \frac{5-4\theta_{\max}}{8-6\theta_{\max}} - \varepsilon,
\end{equation}
one has
\begin{equation} 
    \sum_{\substack{q \le x^{\alpha} \\ (q, a_1 a_2) = 1}} 
    \left\vert \Psi(x, y; a_1 \overline{a_2}, q) - \frac{\Psi_q(x, y)}{\varphi(q)}
    \right\vert 
    \ll_{\varepsilon, A} 
    \Psi(x, y) \left(H(u)^{-\delta} (\log x)^{-A} + y^{-\delta}\right),
\end{equation}

for all $a_1, a_2 \in \mathbf{Z}$ with $1 \le |a_1|, |a_2| \le x^\delta$, and all $A \ge 0$. The implicit constant is effective if $A < 1$.

Let $\Phi$ be a smooth function satisfying
\begin{equation} 
    \mathbbm{1}_{[1, 2]} \le \Phi \le \mathbbm{1}_{(0.5, 3)},
\end{equation}
and $||\Phi^{(j)}||_\infty \ll_j 1$ for $j \ge 0$. Then for any $\varepsilon > 0$ and $1 \gg \delta > 0$, under the parameter conditions in 4.2, 5.2, one has
\begin{equation} 
    \Delta \ll_\varepsilon x\sqrt{\frac{R \log x}{K^2} (\mathcal{S}_1 - 2\textnormal{Re} \mathcal{S}_2 + \mathcal{S}_3)}
    + x^{1-\varepsilon},
\end{equation}
where
\begin{equation} 
\begin{aligned}
    \mathcal{S}_1 &:= \sum_{e \in \mathscr{E}} \sum_{(r,a_1a_2)=1} \Phi\left(\frac{r}{R}\right) \sum_{(m,r)=1} \frac{1}{M} \Phi\left(\frac{m}{M}\right) \sum_{\substack{(k_1k_2,re)=1 \\ k_1 \equiv k_2 \ (\textnormal{mod } re) \\ k_i \equiv a_1\overline{a_2m} \ (\textnormal{mod } r)}} u_{k_1} \overline{u_{k_2}},
    \\
    \mathcal{S}_2 &:= \sum_{e \in \mathscr{E}} \sum_{(r,a_1a_2)=1} \Phi\left(\frac{r}{R}\right) \frac{1}{\varphi(re)}  \sum_{\substack{(m,r)=1}} \frac{1}{M} \Phi\left(\frac{m}{M}\right)  \sum_{\substack{(k_1k_2,re)=1 \\ k_2 \equiv a_1\overline{a_2m} \ (\textnormal{mod } r)}} u_{k_1} \omega_D(mk_1 \overline{a_1}a_2; r)\overline{u_{k_2}},
    \\
    \mathcal{S}_3 &:= \sum_{e \in \mathscr{E}} \sum_{ (r,a_1a_2)=1} \Phi\left(\frac{r}{R}\right) \frac{1}{\varphi(r)\varphi(re)} \sum_{(m,r)=1} \frac{1}{M} \Phi\left(\frac{m}{M}\right) \left\vert \sum_{(k,re)=1} u_k \omega_D(mk \overline{a_1}a_2; r)\right\vert^2.
\end{aligned}
\end{equation}

For all sufficiently small $\varepsilon > 0$, there exists $\delta > 0$ such that with the notation in 6.2, the following hold:
\begin{itemize}
\item[(i).] Assuming the ranges in 4.2, there exists a choice of $E$ satisfying 5.2 such that 
\begin{equation} 
    \mathcal{S}_1 - \widehat{\Phi}(0)X_1 \ll_\varepsilon x^{-2\delta} \frac{K^2}{R}.
\end{equation}
\item[(ii).] Assuming both 4.2, 5.2, one has
\begin{align} 
    \mathcal{S}_2 - \widehat{\Phi}(0)X_2 &\ll_\varepsilon x^{-2\delta} \frac{K^2}{R}, \\

    \mathcal{S}_3 - \widehat{\Phi}(0)X_3 &\ll_\varepsilon x^{-2\delta} \frac{K^2}{R}.
\end{align}
\end{itemize}

For all sufficiently small $\varepsilon > 0$ and all $\eta \in (0, 1)$, the following holds. Under the conditions in 4.2, there exists $E$ satisfying 5.2, such that for any positive integers $b, d$ with $b \ll x^{O(\eta)}$ and $d \ll x^{O(1)}$, and for any parameters $K' \ll NL x^{O(\eta)}$, $N' \asymp N x^{O(\eta)}$, $L' \asymp L x^{O(\eta)}$, $T' \ll NL(RE)^{-1} x^{O(\eta)}$, $H' \ll R M^{-1} x^{O(\eta)}$, one has
\begin{equation} 
\begin{aligned}
    \sum_{\substack{k \sim K' \\ (k, b) = 1}} 
    \sum_{\substack{n \sim N' \\ (n, k) = 1}} 
    \sum_{\substack{t \sim T' \\ (t, dk) = 1}} t \left\vert
    \sum_{\substack{e \sim E \\ (e, dk) = 1}}
    \sum_{h \sim H'} 
    \sum_{\substack{\ell \sim L' \\ (\ell, ket) = 1 \\ n \ell \equiv d k \ (\textnormal{mod } et)}} 
    \beta(e, h, \ell)\ \textnormal{e}\left(het \frac{\overline{b n \ell}}{k}\right)
    \right\vert^2
    \\
    \ll_{\varepsilon, \eta} x^{O(\eta) - \varepsilon/2} N^2 L^3,
\end{aligned}
\end{equation}
for any $1$-bounded complex coefficients $\beta(e, h, \ell)$ (independent of $k, n, t$).

For $\eta \in (0, 1)$, $K, N, T, E, H, L \ll x$, and any positive integers $b \ll x^{O(\eta)}$ and $d \ll x$, assuming that $EHT \ll x^{O(\eta)} KNL$, one has
\[
\begin{aligned}
    \mathcal{B}(K, N, T, E, H, L)^2 \ll_\eta\,
    &x^{O(\eta)} \Bigg( N^2 K^2 H^2 T^2 L^2 + K^2 E^2 H^2 T^4 L^2 + N^2 H^4 L^4 + N^2 H^4 T^2 L^2
    \\
    &+ \left(1 + \frac{K^2}{E^4 L^4}\right)^{\theta_{\max}}
    K T^4 E^8 H^2 L^6 N
    \left(1 + \frac{H^2}{E^2L^2}\right) \left(1 + \frac{K}{NL^2}\right)
    \\
    &+
    \left(1 + \frac{K^2}{E^4L^2}\right)^{\theta_{\max}}
    K T^5 E^8 H^2 L^3 N
    \left(1 + \frac{H}{E} + \frac{H^2}{E^2L}\right) \left(1 + \frac{K}{NL} \right)
    \Bigg).
\end{aligned}
\]
